package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;

/** Actual native single-source facts plus explicit pure two-source grouping fixtures; no writer authority. */
class CatalogDayEntityGroupingTest extends CatalogDayOriginalFinalsTest {
    CatalogDayOriginalFinalsService.Captured captured(Fixture f){f.completeSource();return service(f,Clock.fixed(completed.plusSeconds(60),ZoneOffset.UTC)).capture(day);}
    @Test void FourNativeCategoriesGroupEveryReadyOriginalMemberWithoutAllocatingAnything(){
        for(String category:List.of("agent","skill","workflow","model")){
            var f=new Fixture();f.terminal(category);var original=captured(f);int rows=f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);var plan=CatalogDayEntityGrouping.group(original);assertEquals(1,plan.groups().size());var group=plan.groups().getFirst();assertEquals("fictional-entity",group.entityId());assertEquals(category,group.category());assertEquals(1,group.members().size());assertEquals("fictional-current-item",group.members().getFirst().itemId());assertEquals(original.sources().getFirst().result().hash(),group.members().getFirst().finalResultHash());assertEquals(original.closureHash(),plan.closureHash());assertEquals(original.cutoff(),plan.cutoff());assertEquals("complete",plan.coverageState());assertTrue(plan.excluded().isEmpty());assertEquals(plan.hash(),CatalogDayEntityGrouping.group(original).hash());assertThrows(UnsupportedOperationException.class,()->group.members().clear());assertEquals(rows,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(2,f.f.sends);
        }
    }
    @Test void PureTwoSourceSameEntityGroupsOnceAndKeepsEveryOriginalMemberAndDecision(){
        var f=new Fixture();f.terminal("agent");var original=captured(f);var first=original.sources().getFirst();var second=(ObjectNode)CanonicalJson.parse(first.result().json());second.put("run_id","fictional-pure-second-run").put("source_id","fictional-pure-second-source");var stage=(ObjectNode)second.get("stage_result");stage.put("run_id","fictional-pure-second-run").put("source_id","fictional-pure-second-source");var fragment=(ObjectNode)stage.get("fragments").get(0);fragment.put("root_id","fictional-pure-second-root");((ObjectNode)fragment.get("payload").get("items").get(0)).put("item_id","fictional-pure-second-item");var member=(ObjectNode)fragment.get("members").get(0);member.put("itemId","fictional-pure-second-item").put("runId","fictional-pure-second-run").put("sourceId","fictional-pure-second-source");
        String raw=new String(CanonicalJson.bytes(second),java.nio.charset.StandardCharsets.UTF_8),hash=CanonicalJson.hash(CanonicalJson.Domain.CONTENT,second);var entries=new ArrayList<SourceDedupBarrier.Entry>();entries.add(original.closed().closure().entries().stream().filter(e->e.decision()==SourceDedupBarrier.Decision.INCLUDED).findFirst().orElseThrow());entries.add(new SourceDedupBarrier.Entry("fictional-pure-second-source",SourceDedupBarrier.Decision.INCLUDED,"completed",new SourceDedupBarrier.Progress("agent",day,"fictional-pure-second-source",1,"a".repeat(64),"fictional-pure-second-run",1,SourceDedupBarrier.State.COMPLETE,completed,hash)));
        var sources=List.of(new CatalogDayEntityGrouping.Source(first.receipt().runId(),first.receipt().sourceId(),first.result().hash(),first.result().json()),new CatalogDayEntityGrouping.Source("fictional-pure-second-run","fictional-pure-second-source",hash,raw));var plan=CatalogDayEntityGrouping.values("agent",day,original.closureHash(),original.cutoff(),entries,sources);assertEquals(1,plan.groups().size());assertEquals(2,plan.groups().getFirst().members().size());assertEquals(Set.of("fictional-current-item","fictional-pure-second-item"),plan.groups().getFirst().members().stream().map(CatalogDayEntityGrouping.Member::itemId).collect(java.util.stream.Collectors.toSet()));assertEquals(2,CanonicalJson.parse(plan.json()).get("source_decisions").size());
        assertThrows(RuntimeException.class,()->CatalogDayEntityGrouping.values("agent",day,original.closureHash(),original.cutoff(),entries,sources.subList(0,1)));assertThrows(RuntimeException.class,()->CatalogDayEntityGrouping.values("agent",day,original.closureHash(),original.cutoff(),entries,List.of(sources.getFirst(),sources.getFirst())));assertEquals(2,f.f.sends);
    }
    @Test void NativeMissingSourcesKeepPartialCoverageAndPureWrongRolesHashesOrMembersReject(){
        var f=new Fixture();f.secondEnabled=true;f.terminal("model");f.completeSource();var original=service(f,Clock.fixed(SourceDedupBarrier.deadline(day),ZoneOffset.UTC)).capture(day);var plan=CatalogDayEntityGrouping.group(original);assertEquals("partial",plan.coverageState());assertEquals(1,plan.groups().size());assertEquals(2,CanonicalJson.parse(plan.json()).get("source_decisions").size());var source=original.sources().getFirst();var bad=(ObjectNode)CanonicalJson.parse(source.result().json());((ObjectNode)bad.get("stage_result").get("fragments").get(0).get("members").get(0)).put("category","agent");String raw=new String(CanonicalJson.bytes(bad),java.nio.charset.StandardCharsets.UTF_8),hash=CanonicalJson.hash(CanonicalJson.Domain.CONTENT,bad);
        var entries=original.closed().closure().entries();assertThrows(RuntimeException.class,()->CatalogDayEntityGrouping.values("model",day,original.closureHash(),original.cutoff(),entries,List.of(new CatalogDayEntityGrouping.Source(source.receipt().runId(),source.receipt().sourceId(),hash,raw))));assertThrows(RuntimeException.class,()->CatalogDayEntityGrouping.values("news_tech",day,original.closureHash(),original.cutoff(),entries,List.of()));assertEquals(2,f.f.sends);
    }
}
